# δm: the self-inertia, the order-1 force -δm a.
function self_inertia(Q, ℓ)
    T = typeof(ℓ)
    return _q(T, 693, 4199) * Q^2 * ℓ^(-1) / T(π)
end

# ∬ ρ₀ρ₀′ |x - x′|.
function rho_rho_r(Q, ℓ)
    T = typeof(ℓ)
    return _q(T, 60984, 96577) * Q^2 * ℓ^1
end

# The order-3 force is self_force_addot · ä + self_force_a2a · a² a.
function self_force_addot(Q, ℓ)
    T = typeof(ℓ)
    return _q(T, -2541, 96577) * Q^2 * ℓ^1 / T(π)
